CATALOG;

    private function catalog(): array
    {
        return json_decode(self::CATALOG_JSON, true, 512, JSON_THROW_ON_ERROR);
    }

    public function up(): void
    {
        if (!Schema::hasColumn('test_items', 'reverse_score')) {
            Schema::table('test_items', function (Blueprint $table): void {
                $table->boolean('reverse_score')->default(false);
            });
        }

        DB::transaction(function (): void {
            $catalog = $this->catalog();
            $changedTestIds = [];

            foreach ($catalog as $code => $testSpec) {
                $test = DB::table('tests')
                    ->where('id', (int) $testSpec['test_id'])
                    ->where('code', $code)
                    ->first();

                if (!$test) {
                    throw new \RuntimeException(
                        "Тест {$code} (tests.id={$testSpec['test_id']}) не найден. "
                        . 'Миграция отменена без частичных изменений.'
                    );
                }

                $changedTestIds[] = (int) $test->id;

                foreach ($testSpec['items'] as $itemIdString => $itemSpec) {
                    $itemId = (int) $itemIdString;
                    $item = DB::table('test_items')
                        ->where('id', $itemId)
                        ->where('test_id', (int) $test->id)
                        ->first();

                    if (!$item) {
                        throw new \RuntimeException(
                            "Вопрос test_items.id={$itemId} не принадлежит тесту {$code}."
                        );
                    }

                    if (isset($itemSpec['question'])) {
                        $newQuestion = (string) $itemSpec['question'];
                        $oldQuestion = (string) $itemSpec['old_question'];

                        if ((string) $item->text !== $newQuestion) {
                            if ((string) $item->text !== $oldQuestion) {
                                throw new \RuntimeException(
                                    "Текст вопроса {$itemId} уже изменён вручную. "
                                    . 'Миграция не будет его перезаписывать.'
                                );
                            }

                            DB::table('test_items')
                                ->where('id', $itemId)
                                ->update([
                                    'text' => $newQuestion,
                                    'updated_at' => now(),
                                ]);
                        }
                    }

                    $options = DB::table('test_item_options')
                        ->where('item_id', $itemId)
                        ->orderBy('order')
                        ->orderBy('id')
                        ->get()
                        ->values();

                    $expectedIds = array_map('intval', $itemSpec['option_ids']);
                    $existingCount = count($expectedIds);

                    if ($options->count() < $existingCount) {
                        throw new \RuntimeException(
                            "В тесте {$code}, вопросе {$itemId} меньше вариантов, чем в выгрузке."
                        );
                    }

                    foreach ($expectedIds as $index => $optionId) {
                        $option = $options->get($index);
                        $oldLabel = (string) $itemSpec['old_labels'][$index];
                        $oldValue = (int) $itemSpec['old_values'][$index];
                        $newLabel = (string) $itemSpec['labels'][$index];
                        $newValue = (int) $itemSpec['values'][$index];
                        $previousLabels = array_map(
                            'strval',
                            $itemSpec['previous_labels'] ?? []
                        );

                        if (
                            (int) $option->id !== $optionId
                            || (int) $option->item_id !== $itemId
                        ) {
                            throw new \RuntimeException(
                                "Нарушен порядок/состав вариантов {$code}, question={$itemId}."
                            );
                        }

                        $alreadyUpdated =
                            (string) $option->label === $newLabel
                            && (int) $option->value === $newValue;

                        if ($alreadyUpdated) {
                            continue;
                        }

                        $knownPreviousLabel =
                            (string) $option->label === $oldLabel
                            || in_array((string) $option->label, $previousLabels, true);

                        if (
                            !$knownPreviousLabel
                            || (
                                (int) $option->value !== $oldValue
                                && (int) $option->value !== $newValue
                            )
                        ) {
                            throw new \RuntimeException(
                                "Вариант test_item_options.id={$optionId} изменён вручную. "
                                . 'Миграция не будет перезаписывать неизвестное значение.'
                            );
                        }

                        DB::table('test_item_options')
                            ->where('id', $optionId)
                            ->update([
                                'label' => $newLabel,
                                'value' => $newValue,
                                'updated_at' => now(),
                            ]);
                    }

                    foreach ($itemSpec['append'] as $append) {
                        $existingFifth = DB::table('test_item_options')
                            ->where('item_id', $itemId)
                            ->where('order', (int) $append['order'])
                            ->first();

                        if ($existingFifth) {
                            if (
                                (string) $existingFifth->label !== (string) $append['label']
                                || (int) $existingFifth->value !== (int) $append['value']
                            ) {
                                throw new \RuntimeException(
                                    "Пятый вариант вопроса {$itemId} уже существует с другим содержимым."
                                );
                            }

                            continue;
                        }

                        DB::table('test_item_options')->insert([
                            'item_id' => $itemId,
                            'label' => (string) $append['label'],
                            'value' => (int) $append['value'],
                            'order' => (int) $append['order'],
                            'created_at' => now(),
                            'updated_at' => now(),
                        ]);
                    }
                }
            }

            // Обратное кодирование задаётся для конкретных вопросов.
            $reverseItemsByTest = [
                8 => [85], // DAST-10: пункт 3
                10 => [100, 101, 106, 109, 111, 112, 113, 115], // Zung SDS: позитивные пункты
                15 => [189, 190, 193, 195], // PSS-10: позитивные пункты текущей версии
            ];

            foreach ($reverseItemsByTest as $testId => $itemIds) {
                $updated = DB::table('test_items')
                    ->where('test_id', (int) $testId)
                    ->whereIn('id', $itemIds)
                    ->update(['reverse_score' => true]);

                if ($updated !== count($itemIds)) {
                    throw new \RuntimeException(
                        "Не удалось установить обратное кодирование для test_id={$testId}."
                    );
                }
            }

            $this->updateResourceProfile(5, function (array $profile): array {
                $profile['about'] = 'Суммарная частота ответов по 18 пунктам (0–72). Это описательный показатель данной версии и не заменяет стандартный пороговый подсчёт Part A ASRS.';
                if (isset($profile['bands'][0])) {
                    $profile['bands'][0]['min'] = 0;
                }
                return $profile;
            });

            $this->updateResourceProfile(6, function (array $profile): array {
                $profile['about'] = 'Сумма EPDS: 0–30. Ненулевой ответ на пункт 10 требует отдельной оценки безопасности независимо от общей суммы.';
                $profile['bands'] = [
                    ['min' => 0, 'max' => 9, 'label' => 'Ниже порога', 'text' => 'Результат ниже часто используемого порога скрининга. Это не исключает клинических проблем.'],
                    ['min' => 10, 'max' => 12, 'label' => 'Повышенный результат', 'text' => 'Повышенный результат; требуется клиническая оценка.'],
                    ['min' => 13, 'max' => 30, 'label' => 'Высокий результат', 'text' => 'Рекомендуется клиническая оценка.'],
                ];
                return $profile;
            });

            $this->updateResourceProfile(10, function (array $profile): array {
                $profile['about'] = 'Zung SDS: 20 пунктов, сырой балл 20–80; индекс рассчитывается как сырой балл × 1,25. Положительно сформулированные пункты кодируются в обратном направлении.';
                $profile['bands'] = [
                    ['min' => 20, 'max' => 39, 'label' => 'Норма', 'text' => 'Индекс ниже 50.'],
                    ['min' => 40, 'max' => 47, 'label' => 'Лёгкие проявления', 'text' => 'Индекс примерно 50–59.'],
                    ['min' => 48, 'max' => 55, 'label' => 'Умеренные проявления', 'text' => 'Индекс примерно 60–69.'],
                    ['min' => 56, 'max' => 80, 'label' => 'Выраженные проявления', 'text' => 'Индекс 70 и выше; требуется клиническая оценка.'],
                ];
                return $profile;
            });

            $this->updateResourceProfile(11, function (array $profile): array {
                $profile['about'] = 'Zung SAS: 20 пунктов, сырой балл 20–80; индекс рассчитывается как сырой балл × 1,25.';
                $profile['bands'] = [
                    ['min' => 20, 'max' => 35, 'label' => 'Норма', 'text' => 'Индекс ниже 45.'],
                    ['min' => 36, 'max' => 47, 'label' => 'Лёгкая/умеренная тревога', 'text' => 'Индекс примерно 45–59.'],
                    ['min' => 48, 'max' => 59, 'label' => 'Выраженная тревога', 'text' => 'Индекс примерно 60–74.'],
                    ['min' => 60, 'max' => 80, 'label' => 'Тяжёлая тревога', 'text' => 'Индекс 75 и выше; требуется клиническая оценка.'],
                ];
                return $profile;
            });

            // Пересчитываем уже сохранённые результаты по исправленным шкалам.
            $sessionIds = DB::table('test_sessions')
                ->whereIn('test_id', array_values(array_unique($changedTestIds)))
                ->whereIn('status', [
                    'submitted',
                    'in_review',
                    'coding_done',
                    'completed',
                    'complete',
                    'finished',
                ])
                ->orderBy('id')
                ->pluck('id');

            $scoring = app(TestScoringService::class);

            foreach ($sessionIds as $sessionId) {
                $session = TestSession::query()->find((int) $sessionId);
                if ($session) {
                    $scoring->scoreAndPersist($session);
                }
            }
        });
    }

    private function updateResourceProfile(int $testId, callable $callback): void
    {
        $test = DB::table('tests')->where('id', $testId)->first();

        if (!$test) {
            throw new \RuntimeException("tests.id={$testId} не найден.");
        }

        $profile = $test->resource_profile;

        if (is_string($profile)) {
            $profile = json_decode($profile, true);
        }

        if (!is_array($profile)) {
            $profile = [];
        }

        $profile = $callback($profile);

        DB::table('tests')
            ->where('id', $testId)
            ->update([
                'resource_profile' => json_encode(
                    $profile,
                    JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
                ),
            ]);
    }

    public function down(): void
    {
        // Данные опросников и уже пересчитанные результаты являются частью истории.
        // Откат этого исправления выполняется восстановлением резервной копии БД.
        throw new \RuntimeException(
            'Миграция ответов тестирований является однонаправленной. '
            . 'Для отката восстановите резервную копию БД.'
        );
    }
};
